<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';
import Icon from './Icon.vue';import P6Dialog from './P6Dialog.vue';import {money} from './tradeAmounts';import './p6.css';
type Row=Record<string,any>;type Panel=Row&{id:string;name:string;states:Row[];trend:Row[];canExport:boolean;costVisible:boolean};
const props=defineProps<{request:<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;download:(path:string,name:string)=>Promise<void>}>();
const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const filter=reactive({from:date.slice(0,8)+'01',to:date,owner:'',department:'',region:'',industry:''});
const applied=ref(''),data=ref<Row|null>(null),busy=ref(false),error=ref(''),tab=ref('overview'),options=ref<Row>({owners:[],departments:[],regions:[],industries:[]});
const drill=ref<{panel:Panel;dimension:string;value:string;label:string}|null>(null),items=ref<Row[]>([]),total=ref(0),page=ref(1),loading=ref(false),exporting=ref(false),detailError=ref('');
const names:Record<string,string>={CORE:'核心客户',ACTIVE:'活跃客户',REACTIVATE:'待唤醒客户',DEVELOPING:'待培育客户',CONTACT:'初次接触',NEEDS:'需求确认',SOLUTION:'方案讨论',NEGOTIATION:'报价谈判',READY:'签约准备',WON:'成交',LOST:'丢单',NEW:'新建',CONTACTED:'已联系',QUALIFIED:'合格',UNQUALIFIED:'不合格',CONVERTED:'已转客户',DRAFT:'草稿',SUBMITTED:'待审批',APPROVED:'已批准',REJECTED:'已退回',VOID:'已作废',CONFIRMED:'已确认',IN_DELIVERY:'交付中',DELIVERED:'已交付',RECEIPT:'确认到账',REVERSAL:'回款冲销',IN_PROGRESS:'处理中',WAITING_CUSTOMER:'等待客户',RESOLVED:'已解决',CLOSED:'已关闭',CANCELLED:'已取消',REVIEWED:'已复核',LOCKED:'已锁定',COMPLAINT:'客诉工单',SERVICE:'服务工单',GENERAL:'一般咨询'};
const label=(key:unknown)=>names[String(key)]??(key?String(key):'未填写');
const tabs=[{id:'overview',name:'业务速览'},{id:'customers',name:'客户经营'},{id:'sales',name:'销售与产品'},{id:'cash',name:'订单与回款'},{id:'service',name:'售后与激励'}];
const groups:Record<string,string[]>={overview:['leads','opportunities','quotes','orders','cash'],customers:['customers','rfm'],sales:['opportunities','wins','quotes','products'],cash:['orders','cash'],service:['service','commissions']};
const panels=computed<Panel[]>(()=>data.value?.panels??[]),shown=computed(()=>panels.value.filter(p=>groups[tab.value]?.includes(p.id))),headlines=computed(()=>['customers','wins','orders','cash'].map(id=>panels.value.find(p=>p.id===id)).filter(Boolean) as Panel[]);
const notes:Record<string,string>={customers:'筛选期内创建、当前仍可见的客户。地区与行业按当前档案统计。',leads:'筛选期内创建线索的当前状态；转换比例只针对这批线索。',opportunities:'筛选期内创建商机的当前阶段及预计金额；各阶段不代表累计转化人数。',wins:'按实际成交日期统计，金额为商机实际成交金额。',quotes:'筛选期内创建报价的当前版本与状态；未批准报价不代表收入。',orders:'按确认日期统计有效订单。关联净回款按当前可见合同累计，可能跨越筛选期；无关联合同为零。',cash:'按到账日期计入已确认回款，按冲销日期扣减冲销；可出现负数。',rfm:'覆盖截至期末创建的当前可见客户。R 为最近到账距期末天数，F 为期内确认到账笔数，M 为期内净回款。',products:'按有效订单确认日期统计销售数量、含税金额；预估成本来自订单明细快照。',service:'按工单创建日期统计当前状态；满意度仅包含当前服务周期的有效客户评价。',commissions:'按提成归属月份统计。试算、复核与锁定分别展示；调整为截至查询时的累计调整。'};
const time=computed(()=>data.value?.asOf?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(data.value.asOf)):'');
function query(){const p=new URLSearchParams();for(const [k,v]of Object.entries(filter))if(v)p.set(k,v);return p.toString();}
async function load(){if(busy.value)return;busy.value=true;error.value='';drill.value=null;const q=query();data.value=null;try{data.value=await props.request<Row>('/analytics?'+q);applied.value=q;for(const key of ['owners','departments','regions','industries']){const all=[...options.value[key],...data.value[key]];options.value[key]=[...new Map(all.map((v:any)=>[typeof v==='string'?v:v.id,v])).values()];}}catch(e){error.value=(e as Error).message;options.value={owners:[],departments:[],regions:[],industries:[]};}finally{busy.value=false;}}
function preset(kind:string){filter.to=date;if(kind==='year')filter.from=date.slice(0,4)+'-01-01';else if(kind==='quarter')filter.from=date.slice(0,4)+'-'+String(Math.floor((Number(date.slice(5,7))-1)/3)*3+1).padStart(2,'0')+'-01';else filter.from=date.slice(0,8)+'01';load();}
function reset(){Object.assign(filter,{from:date.slice(0,8)+'01',to:date,owner:'',department:'',region:'',industry:''});load();}
const width=(rows:Row[],row:Row,key='count')=>Math.max(2,Math.abs(Number(row[key]??0))/Math.max(1,...rows.map(x=>Math.abs(Number(x[key]??0))))*100)+'%';
function params(){return applied.value+'&'+new URLSearchParams({dimension:drill.value?.dimension??'',value:drill.value?.value??'',page:String(page.value),pageSize:'20'});}
async function details(){if(!drill.value||loading.value)return;loading.value=true;detailError.value='';items.value=[];total.value=0;try{const r=await props.request<Row>(`/analytics/${drill.value.panel.id}/details?${params()}`);items.value=r.items;total.value=r.total;}catch(e){detailError.value=(e as Error).message;}finally{loading.value=false;}}
function open(panel:Panel,dimension='',value='',title='全部明细'){drill.value={panel,dimension,value,label:title};page.value=1;details();}
async function exportRows(){if(!drill.value||exporting.value)return;exporting.value=true;detailError.value='';try{await props.download(`/analytics/${drill.value.panel.id}/export?${params()}`,`经营分析-${drill.value.panel.name}.csv`);}catch(e){detailError.value=(e as Error).message;}finally{exporting.value=false;}}
function turn(delta:number){page.value+=delta;details();}
function margin(p:Row){return p.costCents==null?'—':money(BigInt(String(p.amountCents??0))-BigInt(String(p.costCents)));}
function rate(p:Row){const n=Number(p.amountCents);return n?((n-Number(p.costCents))/n*100).toFixed(1)+'%':'—';}
onMounted(load);
</script>
<template>
<section class="p6 analytics-workspace" :aria-busy="busy">
 <div class="page-heading"><div><span class="eyebrow">BUSINESS INTELLIGENCE</span><h1>经营指挥台</h1><p>从客户经营到订单回款，在当前授权范围内查看真实业务。</p></div><button class="btn secondary" :disabled="busy" @click="load"><Icon name="refresh" :size="16"/>刷新数据</button></div>
 <form class="p6-card analytics-filters" @submit.prevent="load"><fieldset :disabled="busy"><label>开始日期<input v-model="filter.from" type="date" required :max="filter.to"/></label><label>结束日期<input v-model="filter.to" type="date" required :min="filter.from"/></label><label>业务负责人<select v-model="filter.owner"><option value="">当前可见范围</option><option v-for="x in options.owners" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>部门<select v-model="filter.department"><option value="">全部可见部门</option><option v-for="x in options.departments" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>地区<select v-model="filter.region"><option value="">全部地区</option><option v-for="x in options.regions" :key="x">{{x}}</option></select></label><label>行业<select v-model="filter.industry"><option value="">全部行业</option><option v-for="x in options.industries" :key="x">{{x}}</option></select></label></fieldset><div class="p6-actions"><button class="btn primary" :disabled="busy">应用筛选</button><button type="button" class="btn secondary" :disabled="busy" @click="preset('month')">本月</button><button type="button" class="btn secondary" :disabled="busy" @click="preset('quarter')">本季度</button><button type="button" class="btn secondary" :disabled="busy" @click="preset('year')">本年</button><button type="button" class="text-button" :disabled="busy" @click="reset">重置条件</button><small>上海时区 · 最多跨366天</small></div></form>
 <p v-if="error" class="p6-error" role="alert">{{error}}</p><p v-if="busy" class="p6-muted" role="status">正在核对业务指标与访问范围…</p>
 <template v-if="data"><div class="analytics-context"><span>统计区间 {{data.from}} 至 {{data.to}}</span><span>更新于 {{time}} · 点击图表查看明细</span></div><div class="p6-kpis analytics-kpis"><button v-for="p in headlines" :key="p.id" class="analytics-kpi" @click="open(p)"><span>{{p.name}}</span><strong>{{p.id==='customers'?p.count:money(p.amountCents)}}</strong><small>{{p.id==='customers'?'当前授权范围内':`${p.count} 笔业务记录`}} <span aria-hidden="true">↗</span></small></button></div>
 <div class="p6-tabs" role="group" aria-label="经营分析分类"><button v-for="x in tabs" :key="x.id" class="btn secondary" :class="{active:tab===x.id}" :aria-pressed="tab===x.id" @click="tab=x.id">{{x.name}}</button></div>
 <div class="analytics-grid"><article v-for="p in shown" :key="p.id" class="p6-card analytics-panel"><header><h2>{{p.name}}</h2><button class="text-button" @click="open(p)">查看明细 <span aria-hidden="true">↗</span></button></header><div class="analytics-numbers"><strong>{{['customers','leads','service','rfm'].includes(p.id)?`${p.count} ${p.id==='service'?'单':'个'}`:money(p.amountCents)}}</strong><span v-if="p.id==='rfm'">期内净回款 {{money(p.amountCents)}}</span><span v-else-if="p.id==='orders'&&p.auxCents!=null">关联累计净回款 {{money(p.auxCents)}} · 订单金额差额 {{money(BigInt(String(p.amountCents))-BigInt(String(p.auxCents)))}}</span><span v-else-if="p.id==='commissions'">累计调整 {{money(p.auxCents)}}</span><span v-else-if="p.id==='service'">满意度 {{p.satisfaction==null?'暂无评价':Number(p.satisfaction).toFixed(1)+' / 5'}} · {{p.feedbackCount}} 份有效评价</span><span v-else>{{p.count}} 笔记录</span></div><div v-if="p.costVisible" class="analytics-margin"><span>预估成本 <b>{{money(p.costCents)}}</b></span><span>预估毛利 <b>{{margin(p)}}</b></span><span>毛利率 <b>{{rate(p)}}</b></span></div>
 <div v-if="p.id==='leads'&&p.count" class="analytics-margin"><span>本期创建线索的当前转化率 <b>{{((p.states.find((x:Row)=>x.key==='CONVERTED')?.count??0)/p.count*100).toFixed(1)}}%</b></span></div><p class="p6-muted analytics-note">{{notes[p.id]}}</p><p v-if="!p.count" class="analytics-empty">当前筛选范围暂无业务记录</p>
 <div v-if="p.id==='products'" class="analytics-bars"><button v-for="r in p.products" :key="r.key" @click="open(p,'product',r.key,r.name)"><span class="analytics-bar-label">{{r.name}}<small>数量 {{r.quantity}} · {{money(r.amountCents)}}</small></span><span class="analytics-track"><i :style="{width:width(p.products,r,'amountCents')}"></i></span><b v-if="p.costVisible">毛利 {{margin(r)}}</b></button></div>
 <div v-else class="analytics-bars"><button v-for="r in p.states" :key="r.key" @click="open(p,'state',r.key,label(r.key))"><span class="analytics-bar-label">{{label(r.key)}}<small>{{r.count}} 笔{{['customers','leads','service'].includes(p.id)?'':' · '+money(r.amountCents)}}</small></span><span class="analytics-track"><i :class="{negative:Number(r.amountCents)<0}" :style="{width:width(p.states,r)}"></i></span><b>{{r.count}}</b></button></div>
 <template v-if="p.id==='customers'"><h3>地区分布</h3><div class="analytics-chips"><button v-for="r in p.regions" :key="r.key" @click="open(p,'region',r.key,r.key||'未填写地区')">{{r.key||'未填写'}} <b>{{r.count}}</b></button></div><h3>行业分布</h3><div class="analytics-chips"><button v-for="r in p.industries" :key="r.key" @click="open(p,'industry',r.key,r.key||'未填写行业')">{{r.key||'未填写'}} <b>{{r.count}}</b></button></div></template>
 <template v-if="p.id==='service'"><h3>工单类型</h3><div class="analytics-chips"><button v-for="r in p.types" :key="r.key" @click="open(p,'type',r.key,label(r.key))">{{label(r.key)}} <b>{{r.count}}</b></button></div></template>
 <p v-if="p.id==='rfm'" class="p6-muted">核心：R≤30天、F≥2且M&gt;0；活跃：R≤90天且M&gt;0；待唤醒：R&gt;90天且M&gt;0；待培育：M≤0或未到账。该分层用于销售跟进参考。</p>
 <template v-if="p.trend.length&&p.id!=='rfm'"><h3>月度{{['customers','leads','service'].includes(p.id)?'数量':'金额'}}趋势</h3><div class="analytics-trend"><button v-for="r in p.trend" :key="r.month" @click="open(p,'month',r.month.slice(0,7),r.month.slice(0,7))"><span class="analytics-trend-track"><i :class="{negative:Number(r.amountCents)<0}" :style="{height:width(p.trend,r,['customers','leads','service'].includes(p.id)?'count':'amountCents')}"></i></span><b>{{['customers','leads','service'].includes(p.id)?r.count:money(r.amountCents)}}</b><small>{{r.month.slice(0,7)}}</small></button></div></template>
 </article></div><p v-if="!shown.length" class="p6-card p6-muted">当前角色没有此分类的业务数据权限。</p><p class="p6-muted">金额单位为人民币。不同业务阶段分别统计，不应相加作为收入；产品与订单毛利均为预估口径。导出最多5000行，所有筛选和下钻均重新核验数据权限。</p></template>
 <P6Dialog v-if="drill" :title="drill.panel.name+' · '+drill.label" :busy="loading||exporting" @close="!loading&&!exporting&&(drill=null)"><p class="p6-muted">{{data?.from}} 至 {{data?.to}} · {{notes[drill.panel.id]}}</p><div class="p6-actions"><button v-if="drill.panel.canExport" class="btn secondary" :disabled="loading||exporting||total>5000||!total" @click="exportRows">{{exporting?'正在导出…':'导出当前明细'}}</button><small v-if="total>5000">请缩小筛选范围后导出。</small><small>共 {{total}} 条</small></div><p v-if="detailError" class="p6-error" role="alert">{{detailError}}</p><div class="analytics-table"><table><thead><tr><th>业务名称 / 客户</th><th>负责人 / 日期</th><th>状态</th><th>金额</th><th v-if="drill.panel.costVisible">预估成本 / 毛利</th><th v-if="drill.panel.id==='rfm'">R / F</th><th v-if="drill.panel.id==='service'">评分</th><th v-if="drill.panel.id==='commissions'||drill.panel.id==='orders'">{{drill.panel.id==='orders'?'累计净回款':'累计调整'}}</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td>{{r.title}}<small>{{r.customerName}}</small></td><td>{{r.ownerName}}<small>{{r.eventDate}}</small></td><td>{{label(r.state)}}</td><td>{{['customers','leads','service'].includes(drill.panel.id)?'—':money(r.amountCents)}}</td><td v-if="drill.panel.costVisible">{{money(r.costCents)}}<small>{{margin(r)}}</small></td><td v-if="drill.panel.id==='rfm'">{{r.recencyDays==null?'无到账':r.recencyDays+' 天'}} / {{r.frequency}} 笔</td><td v-if="drill.panel.id==='service'">{{r.score??'未评价'}}</td><td v-if="drill.panel.id==='commissions'||drill.panel.id==='orders'">{{money(r.auxCents)}}</td></tr><tr v-if="!items.length"><td colspan="8" class="p6-muted">{{loading?'正在加载明细…':'当前没有可见明细'}}</td></tr></tbody></table></div><div class="p6-pages"><span>第 {{page}} 页 · 每页20条</span><button class="btn secondary" :disabled="loading||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="loading||page*20>=total" @click="turn(1)">下一页</button></div></P6Dialog>
</section>
</template>
<style scoped>
.analytics-filters fieldset{grid-template-columns:repeat(6,minmax(110px,1fr));gap:12px}.analytics-context{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;color:#a8bbd4;font-size:12px}.analytics-kpi{text-align:left;border:1px solid #6f91c13a;background:linear-gradient(120deg,#1b3551cc,#1b2445b3);border-radius:12px;padding:18px;color:#c6d8ee;cursor:pointer;transition:border-color .2s}.analytics-kpi:hover{border-color:#7de1d3}.analytics-kpi small{display:block;margin-top:10px}.analytics-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}.analytics-panel header{display:flex;align-items:center;justify-content:space-between;gap:12px}.analytics-panel h2{font-size:17px;margin:0}.analytics-panel h3{font-size:12px;color:#a8bbd4;margin:20px 0 10px}.analytics-numbers{display:flex;align-items:baseline;gap:15px;flex-wrap:wrap;margin:20px 0 8px}.analytics-numbers>strong{font-size:27px;font-variant-numeric:tabular-nums}.analytics-numbers>span{font-size:12px;color:#a8bbd4}.analytics-note{min-height:44px}.analytics-bars{display:grid;gap:8px;margin-top:16px}.analytics-bars>button{display:flex;align-items:center;gap:12px;background:#16263f85;border:1px solid transparent;border-radius:8px;padding:11px;color:#d7e5f8;cursor:pointer;text-align:left;min-width:0}.analytics-bars>button:hover,.analytics-chips>button:hover{border-color:#61d4c3}.analytics-bar-label{width:43%;min-width:90px;font-size:13px;overflow-wrap:anywhere}.analytics-bar-label small{display:block;font-size:11px;margin-top:5px}.analytics-bars b{font-size:12px;font-weight:500;white-space:nowrap}.analytics-track{height:7px;flex:1;background:#30405a;border-radius:8px}.analytics-track i{display:block;height:100%;border-radius:8px;background:linear-gradient(90deg,#6c69e9,#61d4c3)}.analytics-track i.negative,.analytics-trend i.negative{background:#ed8a9d}.analytics-chips{display:flex;gap:8px;flex-wrap:wrap}.analytics-chips button{padding:8px 11px;background:#213252;border:1px solid #6983a75a;border-radius:8px;color:#cfdef2;cursor:pointer}.analytics-chips b{margin-left:8px;color:#80e3d3}.analytics-margin{display:flex;gap:15px;flex-wrap:wrap;border-block:1px solid #7995bc2e;padding:12px 0;font-size:12px}.analytics-margin span{color:#a8bbd4}.analytics-margin b{color:#b6f1e7;margin-left:5px}.analytics-trend{display:flex;gap:8px;overflow-x:auto;padding:8px 0}.analytics-trend>button{min-width:78px;flex:1;background:transparent;border:0;color:#c5d7ed;font:inherit;font-size:11px;cursor:pointer;text-align:center}.analytics-trend-track{height:76px;display:flex;align-items:end;justify-content:center;border-bottom:1px solid #6983a75a}.analytics-trend i{display:block;width:25px;background:linear-gradient(0deg,#6666df,#64d8c5);border-radius:4px 4px 0 0;min-height:2px}.analytics-trend b,.analytics-trend small{display:block;font-weight:400;margin-top:7px;white-space:nowrap}.analytics-empty{padding:22px;text-align:center;color:#a8bbd4}.analytics-table{overflow:auto;margin-top:16px}.analytics-table td:first-child{min-width:180px;max-width:330px;white-space:normal;overflow-wrap:anywhere}.analytics-workspace button:focus-visible{outline:2px solid #8bf4e1;outline-offset:3px}@media(max-width:1150px){.analytics-filters fieldset{grid-template-columns:repeat(3,minmax(110px,1fr))}}@media(max-width:800px){.analytics-grid{grid-template-columns:1fr}.analytics-filters fieldset{grid-template-columns:repeat(2,minmax(100px,1fr))}}@media(prefers-reduced-motion:reduce){.analytics-kpi{transition:none}}
</style>
